values
  ((select id from public.editions where year = 2027), 'chiara-blazevic', 1, 'Chiara Blazevic', 'Alsace', 24, 176, 'Rantzwiller (Haut-Rhin)', 'Études validées en management et marketing; titulaire d’un BTS communication.', 'Assistante administrative dans une agence de communication à Mulhouse. Elle souhaite reprendre l’entreprise familiale dans l’automobile.', '2026-06-14', 'Kirrwiller', '{}'::text[], '{}'::text[], 'Elle a grandi en Alsace. Son père est d’origine italienne et croate, sa mère est alsacienne.', 'https://www.instagram.com/chiarablazevic.off/', '/images/candidates/chiara-blazevic.jpg', 'https://tf1pro.com/actualites/article/election-de-miss-france-2027', 'https://www.leparisien.fr/culture-loisirs/miss-france/miss-france-2027-decouvrez-les-31-portraits-officiels-des-pretendantes-a-la-couronne-16-11-2026-3WXRLF4XXJFVNG3IWB3MUOM5D4.php', 'https://photo.lefigaro.fr/programme-tv/miss-france/miss-france-2027-photos-individuelles-officielles-des-31-candidates-20261116'),
