  ((select id from public.editions where year = 2027), 'lina-berthelier', 3, 'Lina Berthelier', 'Auvergne', 24, 173, 'Commentry (Allier)', 'Master 2 en école de commerce; passée par une école de commerce parisienne.', 'Ingénieure commerciale en alternance dans le secteur de l’énergie.', '2026-09-18', 'Vichy', '{}'::text[], array['Égalité et place des femmes dans les études, le travail et l’entrepreneuriat.']::text[], 'Elle termine son alternance et souhaite porter la voix des jeunes femmes qui construisent leur parcours professionnel.', 'https://www.instagram.com/linaberthelier/', '/images/candidates/lina-berthelier.jpg', 'https://tf1pro.com/actualites/article/election-de-miss-france-2027', 'https://www.leparisien.fr/culture-loisirs/miss-france/miss-france-2027-decouvrez-les-31-portraits-officiels-des-pretendantes-a-la-couronne-16-11-2026-3WXRLF4XXJFVNG3IWB3MUOM5D4.php', 'https://photo.lefigaro.fr/programme-tv/miss-france/miss-france-2027-photos-individuelles-officielles-des-31-candidates-20261116'),
  ((select id from public.editions where year = 2027), 'ilona-perrot', 4, 'Ilona Perrot', 'Bourgogne', 23, 176, 'La Fermeté (Nièvre)', 'Formation en soins infirmiers.', 'Infirmière spécialisée en soins psychiatriques.', '2026-05-31', 'Autun', '{}'::text[], array['Sensibilisation à la santé mentale.', 'Don du sang et sensibilisation aux besoins des banques de sang.']::text[], 'Originaire d’un village nivernais d’environ 600 habitants, elle souhaite utiliser son titre pour parler de santé et de solidarité.', 'https://www.instagram.com/ilonaperrot.off/', '/images/candidates/ilona-perrot.jpg', 'https://tf1pro.com/actualites/article/election-de-miss-france-2027', 'https://www.leparisien.fr/culture-loisirs/miss-france/miss-france-2027-decouvrez-les-31-portraits-officiels-des-pretendantes-a-la-couronne-16-11-2026-3WXRLF4XXJFVNG3IWB3MUOM5D4.php', 'https://photo.lefigaro.fr/programme-tv/miss-france/miss-france-2027-photos-individuelles-officielles-des-31-candidates-20261116'),
