  ((select id from public.editions where year = 2027), 'pauline-gourlez', 21, 'Pauline Gourlez', 'Normandie', 22, 171, 'Giberville (Calvados)', null, 'Comptable et mannequin.', '2026-05-22', 'Caen', array['Équitation; elle a été cavalière.']::text[], '{}'::text[], 'Née dans le Nord-Pas-de-Calais, elle a déménagé en Normandie avec sa famille à l’âge de 7 ans et vit près de Caen.', 'https://www.instagram.com/paulinegourlez/', '/images/candidates/pauline-gourlez.jpg', 'https://tf1pro.com/actualites/article/election-de-miss-france-2027', 'https://www.leparisien.fr/culture-loisirs/miss-france/miss-france-2027-decouvrez-les-31-portraits-officiels-des-pretendantes-a-la-couronne-16-11-2026-3WXRLF4XXJFVNG3IWB3MUOM5D4.php', 'https://photo.lefigaro.fr/programme-tv/miss-france/miss-france-2027-photos-individuelles-officielles-des-31-candidates-20261116'),
  ((select id from public.editions where year = 2027), 'lana-prost', 22, 'Lana Prost', 'Nouvelle-Calédonie', 18, 175, 'Le Mont-Dore (Nouvelle-Calédonie)', 'Élève en terminale générale.', 'Étudiante et animatrice radio.', '2026-07-25', 'Nouméa', '{}'::text[], '{}'::text[], 'Élue à 17 ans, elle a eu 18 ans quelques semaines plus tard. Elle a dû organiser avec son lycée le passage du baccalauréat, dont les dates chevauchent le concours national.', 'https://www.instagram.com/lana_prost_/', '/images/candidates/lana-prost.jpg', 'https://tf1pro.com/actualites/article/election-de-miss-france-2027', 'https://www.leparisien.fr/culture-loisirs/miss-france/miss-france-2027-decouvrez-les-31-portraits-officiels-des-pretendantes-a-la-couronne-16-11-2026-3WXRLF4XXJFVNG3IWB3MUOM5D4.php', 'https://photo.lefigaro.fr/programme-tv/miss-france/miss-france-2027-photos-individuelles-officielles-des-31-candidates-20261116'),
  ((select id from public.editions where year = 2027), 'maelle-hamon', 23, 'Maëlle Hamon', 'Pays de la Loire', 23, 172, 'Nantes (Loire-Atlantique)', 'Poursuit des études pour devenir professeure des écoles.', 'Éducatrice scolaire et accompagnante d’élèves en situation de handicap (AESH).', '2026-09-11', 'Vallet', '{}'::text[], '{}'::text[], 'Ancienne Miss Loire-Atlantique 2022, elle poursuit son parcours régional avec l’objectif de devenir professeure des écoles.', 'https://www.instagram.com/maellehamonoff/', '/images/candidates/maelle-hamon.jpg', 'https://tf1pro.com/actualites/article/election-de-miss-france-2027', 'https://www.leparisien.fr/culture-loisirs/miss-france/miss-france-2027-decouvrez-les-31-portraits-officiels-des-pretendantes-a-la-couronne-16-11-2026-3WXRLF4XXJFVNG3IWB3MUOM5D4.php', 'https://photo.lefigaro.fr/programme-tv/miss-france/miss-france-2027-photos-individuelles-officielles-des-31-candidates-20261116'),
  ((select id from public.editions where year = 2027), 'marie-villez', 24, 'Marie Villez', 'Picardie', 26, 173, 'Amiens (Somme)', 'Master 2 en communication en alternance.', 'Chargée de communication dans une entreprise du secteur de la formation.', '2026-09-13', 'Beauvais', '{}'::text[], '{}'::text[], 'Ancienne Miss Somme 2024, elle a retenté le concours avec davantage d’assurance. Sa famille la soutient; sa mère a notamment créé un fan-club dans son village d’origine.', 'https://www.instagram.com/marievillezoff/', '/images/candidates/marie-villez.jpg', 'https://tf1pro.com/actualites/article/election-de-miss-france-2027', 'https://www.leparisien.fr/culture-loisirs/miss-france/miss-france-2027-decouvrez-les-31-portraits-officiels-des-pretendantes-a-la-couronne-16-11-2026-3WXRLF4XXJFVNG3IWB3MUOM5D4.php', 'https://photo.lefigaro.fr/programme-tv/miss-france/miss-france-2027-photos-individuelles-officielles-des-31-candidates-20261116'),
  ((select id from public.editions where year = 2027), 'mandy-goudal', 25, 'Mandy Goudal', 'Poitou-Charentes', 38, 174, 'Saintes (Charente-Maritime)', null, 'Propriétaire d’une boutique de robes de mariée.', '2026-09-04', 'Futuroscope', '{}'::text[], '{}'::text[], 'Mère de deux enfants, elle avait déjà tenté le concours en Picardie une quinzaine d’années auparavant. À 38 ans, elle est la candidate la plus âgée de l’histoire du concours.', 'https://www.instagram.com/mandygoudal/', '/images/candidates/mandy-goudal.jpg', 'https://tf1pro.com/actualites/article/election-de-miss-france-2027', 'https://www.leparisien.fr/culture-loisirs/miss-france/miss-france-2027-decouvrez-les-31-portraits-officiels-des-pretendantes-a-la-couronne-16-11-2026-3WXRLF4XXJFVNG3IWB3MUOM5D4.php', 'https://photo.lefigaro.fr/programme-tv/miss-france/miss-france-2027-photos-individuelles-officielles-des-31-candidates-20261116'),
  ((select id from public.editions where year = 2027), 'ophelie-vitalbo', 26, 'Ophélie Vitalbo', 'Provence', 28, 171, 'Velleron (Vaucluse); installée à Paris.', 'Études de kinésithérapie en Belgique.', 'Kinésithérapeute spécialisée dans la santé de la femme.', '2026-07-24', 'Saint-Raphaël', '{}'::text[], '{}'::text[], 'Deuxième dauphine de Miss Provence 2022, elle a également participé à Miss Île-de-France 2023 et y a terminé quatrième dauphine.', 'https://www.instagram.com/ophelievitalbo/', '/images/candidates/ophelie-vitalbo.jpg', 'https://tf1pro.com/actualites/article/election-de-miss-france-2027', 'https://www.leparisien.fr/culture-loisirs/miss-france/miss-france-2027-decouvrez-les-31-portraits-officiels-des-pretendantes-a-la-couronne-16-11-2026-3WXRLF4XXJFVNG3IWB3MUOM5D4.php', 'https://photo.lefigaro.fr/programme-tv/miss-france/miss-france-2027-photos-individuelles-officielles-des-31-candidates-20261116'),
  ((select id from public.editions where year = 2027), 'laetitia-roguet', 27, 'Laëtitia Roguet', 'La Réunion', 21, 172, 'Sainte-Anne (Saint-Benoît, La Réunion)', 'Études en pharmacie pour devenir préparatrice en pharmacie.', null, '2026-08-22', 'Saint-Denis', '{}'::text[], array['Déstigmatisation de la santé mentale et encouragement à demander de l’aide.']::text[], null, 'https://www.instagram.com/laetitiaroguet_/', '/images/candidates/laetitia-roguet.jpg', 'https://tf1pro.com/actualites/article/election-de-miss-france-2027', 'https://www.leparisien.fr/culture-loisirs/miss-france/miss-france-2027-decouvrez-les-31-portraits-officiels-des-pretendantes-a-la-couronne-16-11-2026-3WXRLF4XXJFVNG3IWB3MUOM5D4.php', 'https://photo.lefigaro.fr/programme-tv/miss-france/miss-france-2027-photos-individuelles-officielles-des-31-candidates-20261116'),
  ((select id from public.editions where year = 2027), 'julia-grid-costantino', 28, 'Julia Grid-Costantino', 'Rhône-Alpes', 23, 174, 'Lyon (Rhône)', 'Master en marketing.', 'Chargée de projets dans un laboratoire pharmaceutique; précédemment chargée de marketing pour une marque de cosmétiques.', '2026-09-19', 'Villefranche-sur-Saône', '{}'::text[], '{}'::text[], 'Elle concourait comme Miss Grand Lyon et Miss Rhône. Après une première expérience l’ayant menée à la troisième place de dauphine, elle remporte le titre régional trois ans plus tard.', 'https://www.instagram.com/julia_grid.costantino/', '/images/candidates/julia-grid-costantino.jpg', 'https://tf1pro.com/actualites/article/election-de-miss-france-2027', 'https://www.leparisien.fr/culture-loisirs/miss-france/miss-france-2027-decouvrez-les-31-portraits-officiels-des-pretendantes-a-la-couronne-16-11-2026-3WXRLF4XXJFVNG3IWB3MUOM5D4.php', 'https://photo.lefigaro.fr/programme-tv/miss-france/miss-france-2027-photos-individuelles-officielles-des-31-candidates-20261116'),
  ((select id from public.editions where year = 2027), 'juliette-gauthier', 29, 'Juliette Gauthier', 'Roussillon', 23, 174, 'Le Boulou (Pyrénées-Orientales)', null, 'Kinésithérapeute, notamment auprès de jeunes enfants.', '2026-07-05', 'Canet-en-Roussillon', '{}'::text[], '{}'::text[], 'Elle met son expérience et sa patience au service des personnes qu’elle accompagne.', 'https://www.instagram.com/juliettegauthier___/', '/images/candidates/juliette-gauthier.jpg', 'https://tf1pro.com/actualites/article/election-de-miss-france-2027', 'https://www.leparisien.fr/culture-loisirs/miss-france/miss-france-2027-decouvrez-les-31-portraits-officiels-des-pretendantes-a-la-couronne-16-11-2026-3WXRLF4XXJFVNG3IWB3MUOM5D4.php', 'https://photo.lefigaro.fr/programme-tv/miss-france/miss-france-2027-photos-individuelles-officielles-des-31-candidates-20261116'),
  ((select id from public.editions where year = 2027), 'naila-parotte', 30, 'Naïla Parotte', 'Saint-Martin et Saint-Barthélemy', 22, 182, 'Saint-Martin', null, 'Gestionnaire de garanties pour un groupe automobile.', '2026-08-01', 'Saint-Martin', '{}'::text[], array['Protection animale; projet de création d’une antenne de la SPA pour aider les chiens errants.']::text[], 'Elle souhaite faire découvrir son territoire aux autres candidates lors du voyage de préparation.', 'https://www.instagram.com/naila.parotte_officiel/', '/images/candidates/naila-parotte.jpg', 'https://tf1pro.com/actualites/article/election-de-miss-france-2027', 'https://www.leparisien.fr/culture-loisirs/miss-france/miss-france-2027-decouvrez-les-31-portraits-officiels-des-pretendantes-a-la-couronne-16-11-2026-3WXRLF4XXJFVNG3IWB3MUOM5D4.php', 'https://photo.lefigaro.fr/programme-tv/miss-france/miss-france-2027-photos-individuelles-officielles-des-31-candidates-20261116'),
  ((select id from public.editions where year = 2027), 'leia-diard', 31, 'Leia Diard', 'Tahiti', 22, 172, 'Papeete (Polynésie française); née à Tours (Indre-et-Loire).', null, 'Enseignante de danse traditionnelle tahitienne; donne parfois des cours en milieu carcéral.', '2026-06-26', 'Pirae', '{}'::text[], array['Sensibilisation à l’endométriose.']::text[], 'Sa mère est originaire de Moorea et son père, militaire, d’Angers. Elle représente la Polynésie française après Hinaupoko Devèze.', 'https://www.instagram.com/leiadiard_off/', '/images/candidates/leia-diard.jpg', 'https://tf1pro.com/actualites/article/election-de-miss-france-2027', 'https://www.leparisien.fr/culture-loisirs/miss-france/miss-france-2027-decouvrez-les-31-portraits-officiels-des-pretendantes-a-la-couronne-16-11-2026-3WXRLF4XXJFVNG3IWB3MUOM5D4.php', 'https://photo.lefigaro.fr/programme-tv/miss-france/miss-france-2027-photos-individuelles-officielles-des-31-candidates-20261116')
